"use strict";
GUIDE_DATA_VI.sections.push({"id":"g0","part":0,"title":"Giới thiệu","blocks":[{"level":1,"text":"Project+ trang bị cho các chuyên gia IT những khái niệm cơ bản để quản lý thành công các dự án quy mô nhỏ đến vừa"},{"level":1,"text":"Chứng chỉ này sẽ xác minh rằng ứng viên đạt chuẩn có đủ kiến thức và kỹ năng cần thiết để thực hiện những việc sau:"},{"level":2,"text":"Quản lý vòng đời dự án (project life cycle)"},{"level":2,"text":"Điều phối các dự án quy mô nhỏ đến vừa"},{"level":2,"text":"Kế hoạch truyền thông (communication plan)"},{"level":2,"text":"Nguồn lực và các bên liên quan (resources and stakeholders)"},{"level":2,"text":"Tài liệu dự án (project documentation)"},{"level":2,"text":"Hoàn thành các dự án lớn hơn"},{"level":1,"text":"Chứng chỉ này cũng bao gồm cả hai phương pháp quản lý dự án Waterfall và Agile"},{"level":1,"text":"Quản lý dự án (project management)"},{"level":2,"text":"Việc khởi xướng, lập kế hoạch, thực hiện, kiểm soát và đóng lại công việc của một đội nhóm để đạt được các mục tiêu cụ thể và đáp ứng các tiêu chí thành công cụ thể trong thời gian đã định"},{"level":1,"text":"Bài thi để được cấp chứng chỉ gồm tối đa 90 câu hỏi trong vòng 90 phút"},{"level":2,"text":"Câu hỏi trắc nghiệm (multiple-choice)"},{"level":2,"text":"3 đến 5 câu hỏi tình huống thực hành (performance-based)"},{"level":1,"text":"Bài thi gồm bốn lĩnh vực (domain)"},{"level":2,"text":"Khái niệm quản lý dự án (Project Management Concepts) (33%)"},{"level":2,"text":"Các giai đoạn của vòng đời dự án (Project Life Cycle Phases) (30%)"},{"level":2,"text":"Công cụ và tài liệu (Tools and Documentation) (19%)"},{"level":2,"text":"Kiến thức cơ bản về IT và quản trị (Basics of IT and Governance) (18%)"},{"level":1,"text":"4 mẹo để thành công trong khóa học này"},{"level":2,"text":"Bật phụ đề chi tiết (closed captioning)"},{"level":2,"text":"Nếu muốn bật phụ đề, chỉ cần nhấn nút CC ở dưới cùng của trình phát video"},{"level":2,"text":"Bạn có thể điều chỉnh tốc độ phát video"},{"level":2,"text":"Nhanh hay chậm, tùy bạn chọn"},{"level":2,"text":"Tham gia nhóm hỗ trợ học viên của chúng tôi"},{"level":2,"text":"www.facebook.com/groups/diontraining"},{"level":2,"text":"Trong nhóm, chúng tôi giải đáp thắc mắc của bạn, đăng thêm nội dung miễn phí, và hỗ trợ lẫn nhau xuyên suốt sự nghiệp IT"},{"level":2,"text":"Tải về và in study guide"},{"level":2,"text":"Chúng tôi khuyên bạn nên tải về, in ra, dùng bút đánh dấu, khoanh tròn, ghi chú trực tiếp lên đó — bất cứ thứ gì bạn cần — để có tài liệu tham khảo khi học ngoại tuyến trước kỳ thi"}]},{"id":"g1","part":0,"title":"Mẹo thi","blocks":[{"level":1,"text":"Sẽ không có câu hỏi bẫy"},{"level":2,"text":"Luôn cảnh giác với các phương án gây nhiễu (distractor) hoặc đánh lạc hướng (red herring)"},{"level":2,"text":"Ít nhất một trong bốn phương án được liệt kê được viết ra để đánh lạc hướng bạn khỏi đáp án đúng"},{"level":1,"text":"Chú ý kỹ những từ được in đậm, in nghiêng hoặc viết HOA toàn bộ"},{"level":1,"text":"Trả lời câu hỏi dựa trên kiến thức CompTIA Project+"},{"level":2,"text":"Trong thế giới quản lý dự án, thường không có đáp án đúng 100% cho mọi câu hỏi bạn gặp trong công việc hằng ngày"},{"level":2,"text":"Khi còn phân vân, hãy chọn đáp án đúng trong nhiều tình huống nhất"},{"level":1,"text":"Hiểu các khái niệm trọng tâm của các câu hỏi trong đề thi"},{"level":1,"text":"Đừng học thuộc lòng các thuật ngữ từng chữ, hãy hiểu chúng thay vào đó"},{"level":1,"text":"Trong kỳ thi, các câu trả lời sẽ ở dạng câu hỏi trắc nghiệm"}]},{"id":"g2","part":0,"title":"Cam kết đỗ 100%","blocks":[{"level":1,"text":"Toàn bộ rủi ro thuộc về chúng tôi, đúng như lẽ ra phải thế"},{"level":2,"text":"Bạn không có gì để mất ở đây, nhưng bạn phải làm phần việc của mình và nỗ lực một chút"},{"level":1,"text":"Khi làm các bài quiz, bạn phải đạt tối thiểu 80% mới được coi là đỗ trong hệ thống của chúng tôi"},{"level":1,"text":"Ở cuối khóa học, bạn sẽ tìm thấy các bài thi thử của chúng tôi"},{"level":2,"text":"Hãy hiểu vì sao các đáp án đúng hay sai"},{"level":2,"text":"Giải thích được cung cấp cho từng câu hỏi"},{"level":1,"text":"Xin đừng chỉ cố học thuộc lòng các câu hỏi, mà hãy dành thời gian hiểu lý do đằng sau chúng"},{"level":1,"text":"Hãy đảm bảo rằng bạn đã xem video, làm quiz, thực hành lab và hoàn thành các bài thi thử"},{"level":2,"text":"Nếu bạn đã làm đủ mọi thứ mà phần tiến độ ở trên cùng vẫn chưa chạy từ 0 lên 100, nghĩa là có gì đó không ổn"},{"level":2,"text":"Nếu bạn nghĩ mình đã làm hết mà vẫn không hiển thị 100%, hãy gửi email cho chúng tôi tại support@diontraining.com"},{"level":1,"text":"Khi có thư xác nhận hoàn thành khóa học, bạn đủ điều kiện nhận Cam kết đỗ 100% trong 60 ngày (60-Day 100% Pass Guarantee)"}]},{"id":"g3","part":1,"title":"Vòng đời dự án","blocks":[{"level":1,"text":"Quản lý dự án (project management)"},{"level":2,"text":"Việc khởi xướng, lập kế hoạch, thực hiện, kiểm soát và đóng lại công việc của một đội nhóm để đạt được các mục tiêu cụ thể và đáp ứng các tiêu chí thành công cụ thể trong một khung thời gian xác định"},{"level":1,"text":"Có một khuôn khổ và phương pháp quản lý dự án tốt sẽ giúp ích cho mọi người"},{"level":1,"text":"Quản lý dự án giúp đội nhóm tiết kiệm thời gian, tốn ít tiền hơn và giảm thiểu rủi ro tổng thể của dự án"},{"level":1,"text":"Dự án (project)"},{"level":2,"text":"Một tổ chức tạm thời được tạo ra nhằm mục đích bàn giao một hoặc nhiều sản phẩm kinh doanh theo business case đã được thống nhất"},{"level":2,"text":"Dự án có tính chất tạm thời"},{"level":2,"text":"Nó phải có thời điểm bắt đầu và kết thúc xác định"},{"level":1,"text":"Hoạt động kinh doanh thường xuyên (business as usual)"},{"level":2,"text":"Các hoạt động vận hành kinh doanh tiêu chuẩn và điển hình"},{"level":1,"text":"Một dự án tuân theo một vòng đời bắt đầu bằng business case và lý tưởng nhất là kết thúc bằng một dự án được bàn giao thành công"},{"level":1,"text":"Mọi dự án đều trải qua năm giai đoạn công việc chung"},{"level":2,"text":"Giai đoạn Discovery (Discovery Phase)"},{"level":2,"text":"Diễn ra trước khi dự án bắt đầu"},{"level":2,"text":"Các nhà lãnh đạo và chuyên gia phân tích động não các ý tưởng cho các dự án tiềm năng và xác định xem chúng có khả thi với tổ chức của họ không"},{"level":2,"text":"Giai đoạn Initiation"},{"level":2,"text":"Bạn sẽ tìm hiểu về mục tiêu của dự án, dự án cần bàn giao những gì, và sản phẩm hoặc đầu ra cuối cùng có thể trông như thế nào"},{"level":2,"text":"Giai đoạn này cũng xây dựng đội dự án, trong đó vai trò của từng thành viên được xác định"},{"level":2,"text":"Trong giai đoạn Initiation, đội dự án được thành lập và các vai trò được xác định"},{"level":2,"text":"Giai đoạn Planning"},{"level":2,"text":"Bản tóm tắt cấp cao về mục tiêu của dự án được chi tiết hóa và làm rõ đầy đủ"},{"level":2,"text":"Giai đoạn Execution"},{"level":2,"text":"Công việc này khác nhau tùy theo dự án và tùy theo đội nhóm"},{"level":2,"text":"Đến cuối giai đoạn Execution, đội nhóm đã hoàn thành kế hoạch, và do đó mọi mục tiêu đặt ra ở giai đoạn Initiation đều phải được hoàn thành"},{"level":2,"text":"Giai đoạn Closing"},{"level":2,"text":"Dự án giảm dần hoạt động rồi kết thúc"},{"level":2,"text":"Sản phẩm được bàn giao, các tài khoản thanh toán được đóng để ngăn các khoản phí phát sinh ngoài ý muốn, phản hồi được cung cấp, và các bài học được ghi lại (Project Management Basics)"}]},{"id":"g4","part":1,"title":"Những kiến thức cơ bản về quản lý dự án","blocks":[{"level":1,"text":"Dự án có tính chất tạm thời và được thực hiện để tạo ra một kết quả cụ thể trong một khoảng thời gian xác định"},{"level":1,"text":"Quản lý dự án giúp các công ty đạt được các mục tiêu và mục đích của họ"},{"level":1,"text":"Một dự án phải mang lại giá trị mới chứ không chỉ đơn thuần thực hiện các hoạt động vận hành thông thường của doanh nghiệp"},{"level":1,"text":"Dự án có thể kéo dài từ một ngày đến vài năm"},{"level":1,"text":"Quản lý dự án biến một ý tưởng thành mục tiêu cụ thể và triển khai nó"},{"level":2,"text":"Nó cũng kiểm soát chi phí đồng thời tạo ra các kết quả chất lượng cao"},{"level":1,"text":"Là một ngành học, quản lý dự án hướng đến việc bàn giao công việc một cách trật tự và hiệu quả"},{"level":1,"text":"Các biểu mẫu (template) giúp công việc dễ dàng hơn và đơn giản hóa việc tạo ra các hiện vật dự án (project artifact)"}]},{"id":"g5","part":1,"title":"Kỹ năng quản lý dự án","blocks":[{"level":1,"text":"Quản lý dự án đòi hỏi một tư duy trong đó khả năng thích ứng (adaptability), kỷ luật và các mối quan hệ cá nhân có giá trị ngang nhau"},{"level":1,"text":"Một quản lý dự án (project manager) cần nắm được vô số các bộ phận đang vận hành trong một dự án"},{"level":1,"text":"Các đội dự án phải giữ sự linh hoạt và thích ứng với những thách thức mà họ đối mặt"},{"level":1,"text":"Quản lý dự án cũng cần một lượng đáng kể tư duy phản biện, phân tích và giải quyết vấn đề"},{"level":1,"text":"Các đội dự án thường làm việc trong những lĩnh vực mà họ không sở hữu hệ thống cũng không quản lý con người"},{"level":1,"text":"Các thành viên đội dự án có — hoặc phát triển — kỹ năng hợp tác, lãnh đạo và gây ảnh hưởng xuất sắc"},{"level":1,"text":"Quản lý dự án là một bức tranh ghép từ nhiều tài năng khác nhau, và bạn sẽ học được nhiều kỹ năng quý giá"}]},{"id":"g6","part":1,"title":"Lợi ích của quản lý dự án","blocks":[{"level":1,"text":"Quản lý dự án (project management)"},{"level":2,"text":"Nó được thiết kế để bàn giao công việc một cách hiệu quả và trật tự"},{"level":1,"text":"Quản lý dự án tốt có thể tiết kiệm tiền và tối ưu hóa kết quả cho một tổ chức"},{"level":1,"text":"Quản lý dự án và các quản lý dự án giúp đưa lại trật tự cho công việc phức tạp"},{"level":1,"text":"Khi quản lý một dự án, kế hoạch có thể thay đổi"},{"level":1,"text":"Dự phòng tình huống bất ngờ (contingency reserve)"},{"level":2,"text":"Khoản đệm thời gian và tiền bạc được tính toán để bao phủ các rủi ro đã được ghi nhận"},{"level":1,"text":"Dự phòng quản lý (management reserve)"},{"level":2,"text":"Khoản thời gian hoặc tiền bạc bổ sung bao phủ các \"điều chưa biết mà ta chưa biết\" — những trở ngại mà chúng ta chưa lường trước"},{"level":1,"text":"Lợi ích của việc thực hiện đúng quản lý dự án bao gồm tiết kiệm tiền, tối ưu hóa kết quả và ngăn ngừa các sai lầm tốn kém cho các tổ chức"}]},{"id":"g7","part":1,"title":"Các loại hình công việc","blocks":[{"level":1,"text":"Môi trường làm việc bao quanh một dự án riêng lẻ ảnh hưởng đến cách tiếp cận dự án và trách nhiệm của quản lý dự án"},{"level":1,"text":"Các vai trò, loại hình công việc và cơ cấu tổ chức ảnh hưởng đến giao tiếp, động lực đội nhóm và các mối quan hệ báo cáo"},{"level":1,"text":"2 hạng mục chính của công việc dự án"},{"level":2,"text":"Công việc vận hành (operational work)"},{"level":2,"text":"Công việc thường lệ, có thể dự đoán và lặp đi lặp lại"},{"level":2,"text":"Công việc dự án (project work)"},{"level":2,"text":"Đạt được một điều gì đó mới"},{"level":2,"text":"Một dự án phải đáp ứng ba tiêu chí"},{"level":2,"text":"Nó là duy nhất"},{"level":2,"text":"Nó có một mục tiêu hoàn toàn mới"},{"level":2,"text":"Nó có một mục đích cụ thể"},{"level":2,"text":"Nó có lý do tồn tại"},{"level":2,"text":"Nó là tạm thời"},{"level":2,"text":"Nó có thời điểm bắt đầu và kết thúc xác định"},{"level":1,"text":"Dự án là một nỗ lực tạm thời"}]},{"id":"g8","part":1,"title":"Cơ cấu tổ chức","blocks":[{"level":1,"text":"Cơ cấu tổ chức ảnh hưởng đến quy trình quản lý dự án, cách công việc luân chuyển, cách mọi người lập đội nhóm, và vai trò của quản lý dự án"},{"level":1,"text":"3 cơ cấu tổ chức chính"},{"level":2,"text":"Cơ cấu chức năng (functional)"},{"level":2,"text":"Chia tổ chức thành các lĩnh vực chuyên môn và chuyên môn hóa"},{"level":2,"text":"Sơ đồ tổ chức cho loại cơ cấu này khá trực quan"},{"level":2,"text":"Quản lý chức năng (functional manager) chịu trách nhiệm duy trì ngân sách và quản lý nhân sự"},{"level":2,"text":"Quản lý dự án điều phối dự án"},{"level":2,"text":"Các đội chức năng ít nhận biết về các bộ phận khác trong tổ chức, hoạt động trong các \"ốc đảo thông tin\" (information silo)"},{"level":2,"text":"Cơ cấu theo dự án (projectized)"},{"level":2,"text":"Tổ chức tập trung nguồn lực quanh các dự án như trọng tâm chính"},{"level":2,"text":"Các tổ chức theo dự án mang lại lợi ích cho các công ty dành phần lớn nguồn lực cho công việc dự án"},{"level":2,"text":"Các quản lý dự án có nhiều quyền kiểm soát hơn trong một tổ chức theo dự án"},{"level":2,"text":"Quản lý dự án cũng sở hữu ngân sách và các trách nhiệm quản lý tuyến điển hình"},{"level":2,"text":"Cơ cấu ma trận (matrix)"},{"level":2,"text":"Bao gồm cả các lãnh đạo chức năng và các vai trò chuyên biệt"},{"level":2,"text":"Trong một tổ chức ma trận, các thành viên đội nhóm từ các bộ phận chức năng làm việc trong các đội dự án, bán thời gian hoặc toàn thời gian"},{"level":2,"text":"2 loại cơ cấu tổ chức ma trận"},{"level":2,"text":"Ma trận yếu (weak matrix)"},{"level":2,"text":"Quản lý chức năng giữ trách nhiệm ngân sách và quản lý nhân sự"},{"level":2,"text":"Quản lý dự án có quyền kiểm soát dự án ít hơn một chút"},{"level":2,"text":"Ma trận mạnh (strong matrix)"},{"level":2,"text":"Quản lý dự án có quyền kiểm soát đáng kể đối với dự án"},{"level":2,"text":"Họ vừa có trách nhiệm quản lý nhân sự vừa có trách nhiệm ngân sách"},{"level":2,"text":"Các doanh nghiệp trong gần như mọi ngành đều có thể hoạt động như một tổ chức ma trận"},{"level":2,"text":"Nhược điểm chính của loại cơ cấu này là nhân viên thường chia thời gian giữa công việc vận hành và một hoặc nhiều dự án"}]},{"id":"g9","part":1,"title":"Vai trò và trách nhiệm","blocks":[{"level":1,"text":"Quản lý dự án (project manager)"},{"level":2,"text":"Chịu trách nhiệm lập kế hoạch, tổ chức, lãnh đạo và giữ cho đội nhóm đi đúng hướng và trong ngân sách"},{"level":2,"text":"Các quản lý dự án có mặt để bàn giao dự án đúng thời hạn, trong ngân sách và trong phạm vi"},{"level":1,"text":"Quản lý chương trình (program manager)"},{"level":2,"text":"Những cá nhân dẫn dắt các chương trình hoặc nhóm các dự án liên quan"},{"level":2,"text":"Một quản lý chương trình hoạt động ở cấp độ chiến lược hơn và giám sát nhiều dự án trong một chương trình"},{"level":2,"text":"Là một quản lý dự án, việc duy trì giao tiếp với quản lý chương trình là điều quan trọng"},{"level":1,"text":"Văn phòng quản lý dự án (Project Management Office - PMO)"},{"level":2,"text":"Bộ phận chức năng dành cho tất cả các quản lý dự án trong một công ty"},{"level":2,"text":"Quản lý dòng chảy các dự án và cung cấp hỗ trợ hành chính, như duy trì kho lưu trữ, các thực hành tốt nhất và các công cụ quản lý dự án"},{"level":2,"text":"Giám sát quản lý hiệu quả dự án và theo dõi các chỉ số (metric) cho các dự án trong toàn tổ chức"},{"level":2,"text":"Cung cấp huấn luyện và đào tạo có giá trị cho nhân sự"},{"level":2,"text":"3 loại văn phòng quản lý dự án"},{"level":2,"text":"PMO hỗ trợ (supportive PMO)"},{"level":2,"text":"Cung cấp hỗ trợ khi được yêu cầu"},{"level":2,"text":"PMO kiểm soát (controlling PMO)"},{"level":2,"text":"Giám sát hiệu quả dự án và điều phối việc lựa chọn nguồn lực đồng thời phân bổ quản lý dự án cho các dự án"},{"level":2,"text":"PMO kiểm soát điều phối giao tiếp và đặt ra một số tiêu chuẩn dự án"},{"level":2,"text":"PMO chỉ đạo (directive PMO)"},{"level":2,"text":"Có toàn quyền đối với các dự án, tiêu chuẩn và thủ tục"},{"level":2,"text":"Nó tập trung vào chiến lược tổ chức và sẽ khởi động, hủy bỏ hoặc điều chỉnh các dự án để đảm bảo sự phù hợp chiến lược"},{"level":2,"text":"PMO có động lực đảm bảo các dự án vận hành tốt, và mọi dự án đều liệt kê PMO như một bên liên quan (stakeholder)"},{"level":1,"text":"Một số vai trò ảnh hưởng đến dự án"},{"level":2,"text":"Bên liên quan (stakeholder)"},{"level":2,"text":"Bất kỳ ai có lợi ích gắn liền với dự án"},{"level":2,"text":"Các bên liên quan không phải lúc nào cũng là người ủng hộ"},{"level":2,"text":"Ban lãnh đạo cấp cao (senior management)"},{"level":2,"text":"Cấp lãnh đạo cao nhất trong một tổ chức"},{"level":2,"text":"Nhà tài trợ (sponsor)"},{"level":2,"text":"Một thành viên duy nhất của ban lãnh đạo cấp cao, người xem xét và xác thực business case ban đầu"},{"level":2,"text":"Đảm bảo nguồn tài trợ và loại bỏ các rào cản, khiến họ trở thành tài sản quý giá cho một quản lý dự án"},{"level":2,"text":"Khách hàng (customer)"},{"level":2,"text":"Các bên nhận được lợi ích từ các dự án"},{"level":2,"text":"Khách hàng nội bộ (internal customer)"},{"level":2,"text":"Ở bên trong tổ chức"},{"level":2,"text":"Họ dễ tiếp cận hơn để cung cấp phản hồi trong và sau dự án"},{"level":2,"text":"Khách hàng bên ngoài (external customer)"},{"level":2,"text":"Ở bên ngoài tổ chức"},{"level":2,"text":"Họ có thể tài trợ cho kết quả của dự án"},{"level":2,"text":"Người dùng cuối (end-user)"},{"level":2,"text":"Người sẽ tương tác với đầu ra cuối cùng của dự án"},{"level":2,"text":"Nhà tài trợ, khách hàng và người dùng cuối có thể là cùng một người trong một số trường hợp"}]},{"id":"g10","part":1,"title":"Chương trình và danh mục đầu tư","blocks":[{"level":1,"text":"Mỗi dự án có một mục tiêu duy nhất giải thích những gì nó định đạt được"},{"level":1,"text":"Khi một dự án nằm trong một chương trình, trách nhiệm của quản lý dự án tăng lên"},{"level":1,"text":"Một quản lý dự án cần nhận biết các dự án khác trong chương trình và đánh giá mức độ ảnh hưởng của bất kỳ thay đổi nào của chương trình đối với tiến độ và phạm vi của dự án"},{"level":1,"text":"Các bên liên quan của chương trình và nhân sự chương trình là những bên liên quan bạn sẽ cần xem xét khi đánh giá các tác động"},{"level":1,"text":"Có những ràng buộc ngân sách và các giới hạn nguồn lực khác phải được tính đến"},{"level":2,"text":"Để tránh điều này, hãy dùng danh mục đầu tư (portfolio) và quản lý danh mục đầu tư (portfolio management)"},{"level":2,"text":"Chương trình (program)"},{"level":2,"text":"Nhóm các dự án liên quan"},{"level":2,"text":"Danh mục đầu tư (portfolio)"},{"level":2,"text":"Nhóm của tất cả các dự án và chương trình"},{"level":2,"text":"Các dự án trong một chương trình có liên quan đến cùng một mục tiêu, nhưng các dự án trong một danh mục đầu tư không cần phải liên quan đến nhau"},{"level":2,"text":"Danh mục đầu tư doanh nghiệp (enterprise portfolio)"},{"level":2,"text":"Chứa tất cả các chương trình và dự án trong một tổ chức và được phân rã thành các danh mục đầu tư con ở cấp bộ phận hoặc chi nhánh"},{"level":2,"text":"Quản lý danh mục đầu tư (portfolio management)"},{"level":2,"text":"Cung cấp bối cảnh chiến lược và góc nhìn giúp một tổ chức duy trì số lượng tối đa các dự án và ưu tiên chúng theo các mục tiêu hoặc ưu tiên"},{"level":2,"text":"Một quy trình quản lý danh mục đầu tư thành công giới hạn tổng số lượng dự án"},{"level":1,"text":"Các dự án có thể là một phần của các chương trình và danh mục đầu tư lớn hơn"},{"level":1,"text":"Một chương trình nhóm các dự án liên quan lại với nhau để đạt được một mục tiêu lớn hơn"},{"level":1,"text":"Danh mục đầu tư giúp các tổ chức ưu tiên và thực hiện nhiều dự án và chương trình một cách hiệu quả (The Business Case)"}]},{"id":"g11","part":2,"title":"Business case","blocks":[{"level":1,"text":"Business case là phần quan trọng nhất lý giải vì sao các dự án được thực hiện"},{"level":2,"text":"Nó phải ngắn gọn, trình bày bắt mắt và dễ đọc"},{"level":2,"text":"Nó còn được gọi là \"business justification\" (lý giải kinh doanh) hoặc \"business objective\" (mục tiêu kinh doanh)"},{"level":2,"text":"Nó tóm tắt thông tin về dự án và đóng vai trò là đề xuất dự án đầu tiên"},{"level":1,"text":"Một business case trình bày một phân tích khách quan về vấn đề kinh doanh, các giải pháp tiềm năng và tác động tài chính"},{"level":1,"text":"Business case có thể chứa bất kỳ dữ liệu liên quan nào như"},{"level":2,"text":"Tóm tắt điều hành (executive summary)"},{"level":2,"text":"Một bản tóm tắt ngắn gọn về những gì các phần còn lại của business case sẽ đề cập"},{"level":2,"text":"Đây là cái nhìn tổng quan về các thông tin liên quan quan trọng nhất, thường chỉ dài vài câu, bao gồm"},{"level":2,"text":"Phát biểu vấn đề (problem statement)"},{"level":2,"text":"Giải pháp (solution)"},{"level":2,"text":"Kết quả kỳ vọng (expected result)"},{"level":2,"text":"Phát biểu vấn đề (problem statement)"},{"level":2,"text":"Chia sẻ thêm chi tiết về vấn đề"},{"level":2,"text":"Vấn đề sau đó được phân tích trong phần phân tích vấn đề (problem analysis)"},{"level":2,"text":"Nó cung cấp thêm bối cảnh về lý do dự án nên được ưu tiên và có thể bao gồm bằng chứng để hỗ trợ những điều sau"},{"level":2,"text":"Business Case"},{"level":2,"text":"Đánh giá môi trường (environmental assessment)"},{"level":2,"text":"Dữ liệu lịch sử (historical data)"},{"level":2,"text":"Các lựa chọn (options)"},{"level":2,"text":"So sánh các giải pháp với nhau dựa trên ưu điểm và nhược điểm"},{"level":2,"text":"Việc xác định các phương án thay thế giúp business case có thêm chiều sâu"},{"level":2,"text":"Tổng quan tài chính (financial overview)"},{"level":2,"text":"Chứa phân tích chi phí - lợi ích hoặc lợi tức đầu tư và đưa ra các rủi ro và giả định liên quan"},{"level":2,"text":"Định nghĩa dự án (project definition)"},{"level":2,"text":"Thông tin liên quan bổ sung về dự án được đề xuất"},{"level":2,"text":"Phạm vi dự án (project scope)"},{"level":2,"text":"Nguồn lực (resources)"},{"level":2,"text":"Các cột mốc (milestone)"},{"level":2,"text":"Lịch trình triển khai (implementation timeline)"},{"level":2,"text":"Khuyến nghị dự án (project recommendation)"},{"level":2,"text":"Cung cấp một phân tích về lựa chọn nào có khả năng là giải pháp tốt nhất cho dự án"},{"level":2,"text":"Nó phải phản ánh Tổng quan tài chính, Lợi tức đầu tư và Định nghĩa dự án"},{"level":1,"text":"Viết các phát biểu vấn đề tập trung vào giá trị"},{"level":2,"text":"Một trong những mục tiêu chính của quản lý dự án là tạo ra một business case gây được sự đồng cảm với các bên liên quan và tập trung vào giá trị của dự án thay vì công nghệ"},{"level":2,"text":"Công nghệ chỉ đơn giản là một công cụ hoặc phương tiện giúp giải quyết vấn đề cho doanh nghiệp"},{"level":1,"text":"Một business case tốt trình bày một vấn đề và một kết quả kỳ vọng kèm theo nhiều lựa chọn"},{"level":1,"text":"Viết hồ sơ bằng ngôn ngữ rõ ràng và đơn giản"},{"level":1,"text":"Các yếu tố ESG (Environmental, Social, and Governance)"},{"level":2,"text":"Đề cập đến các hành động và chương trình của một công ty vượt ra ngoài việc tối đa hóa lợi nhuận"}]},{"id":"g12","part":2,"title":"Hiện trạng và trạng thái tương lai","blocks":[{"level":1,"text":"Một business case cần có yếu tố kể chuyện"},{"level":1,"text":"Hiện trạng (current state)"},{"level":2,"text":"Điều gì đang diễn ra với tổ chức ngay lúc này?"},{"level":1,"text":"Trạng thái tương lai (future state)"},{"level":2,"text":"Doanh nghiệp sẽ trông như thế nào sau khi triển khai dự án của bạn?"},{"level":1,"text":"Một phép so sánh tốt cho thấy sự khác biệt rõ ràng giữa hiện trạng và trạng thái tương lai của tổ chức"},{"level":1,"text":"Các phép so sánh đặt cạnh nhau có thể ở dạng trực quan, mô tả, hoặc cả hai, và nó sẽ giúp nhấn mạnh các điểm chính"},{"level":1,"text":"Một bản tóm tắt mô tả có thể mở rộng nhẹ thông tin này với các cải thiện định tính hoặc các khoản đầu tư độc đáo"},{"level":2,"text":"Một bản tóm tắt trực quan cũng có thể được đưa vào"},{"level":2,"text":"Các bản tóm tắt trực quan dùng sơ đồ hoặc biểu đồ để cho thấy sự khác biệt giữa các trạng thái"},{"level":1,"text":"Lưu đồ quy trình (process flowchart)"},{"level":2,"text":"Cho thấy các bước, trình tự và các kết quả có thể xảy ra bằng một bộ hình dạng chuẩn"},{"level":1,"text":"Để tạo một phép so sánh trực quan thuyết phục, bạn có thể tạo một hiện trạng, rồi gạch bỏ các bước sẽ bị loại bỏ"},{"level":1,"text":"Trạng thái tương lai sẽ cho thấy một lưu đồ quy trình được tinh gọn, với ít bước hơn và ít vòng lặp lại hơn"},{"level":1,"text":"Hãy kể chuyện hay khi viết business case của mình"},{"level":1,"text":"Hiện trạng và trạng thái tương lai của bạn nên dùng chung các chỉ số (metric), và có thể dùng các phép so sánh đặt cạnh nhau"}]},{"id":"g13","part":2,"title":"Tác động tài chính","blocks":[{"level":1,"text":"Phân tích tài chính (financial analysis)"},{"level":2,"text":"Còn được gọi là lợi ích tài chính (financial benefit), phân tích chi phí - lợi ích (cost-benefit analysis), hoặc lợi tức kinh tế (economic return)"},{"level":1,"text":"Lợi tức đầu tư (Return on Investment - ROI)"},{"level":2,"text":"So sánh lợi ích tài chính của dự án với chi phí, và nó được viết dưới dạng phần trăm"},{"level":2,"text":"Số dương thể hiện một dự án có lãi"},{"level":2,"text":"Số âm nghĩa là dự án bị lỗ"},{"level":2,"text":"ROI thường được trình bày dưới ba công thức sau, tất cả đều cho ra cùng một kết quả"},{"level":2,"text":"ROI = (Net Profit / Cost) x 100"},{"level":2,"text":"ROI = ((Revenue - Cost) / Cost) x 100"},{"level":2,"text":"ROI = ((Financial Value - Project Cost) / Project Cost) x 100"},{"level":2,"text":"Ba giá trị chính là lợi ích (benefit), chi phí (cost) và lợi nhuận ròng (net profit)"},{"level":2,"text":"Lợi ích (benefit)"},{"level":2,"text":"Số tiền tạo ra hoặc tiết kiệm được một cách rõ ràng nhờ thực hiện dự án"},{"level":2,"text":"Lợi ích thường được gọi là \"giá trị tài chính (financial value)\" hoặc \"doanh thu (revenue)\""},{"level":2,"text":"Biến này là dòng tiền chảy vào công ty"},{"level":2,"text":"Doanh thu (revenues)"},{"level":2,"text":"Giảm chi phí (cost reduction)"},{"level":2,"text":"Tránh chi phí (cost avoidance)"},{"level":2,"text":"Các khoản lợi tức đo lường được khác"},{"level":2,"text":"Chi phí (cost)"},{"level":2,"text":"Thường được gọi là \"chi phí dự án (project cost)\" hoặc \"chi phí phát sinh của dự án (project expense)\", biến này là dòng tiền chảy ra khỏi công ty"},{"level":2,"text":"Các khoản chi phí sẽ bao gồm chi phí trực tiếp và chi phí gián tiếp"},{"level":2,"text":"Nhân công (labor)"},{"level":2,"text":"Thiết bị (equipment)"},{"level":2,"text":"Hợp đồng (contract)"},{"level":2,"text":"Lợi nhuận ròng (net profit)"},{"level":2,"text":"Chênh lệch giữa lợi ích và chi phí"},{"level":1,"text":"Bối cảnh kinh doanh, các quy định và các yêu cầu về môi trường là một trong nhiều yếu tố ảnh hưởng đến việc phê duyệt dự án"},{"level":1,"text":"Phân tích tài chính bao gồm việc gán các con số cụ thể cho các sự kiện trong tương lai"},{"level":1,"text":"Chúng ta càng cố hoạch định hoặc gán số cho một điều gì đó ở càng xa trong tương lai, độ chính xác của chúng ta càng tệ"},{"level":1,"text":"Sẽ hữu ích khi đưa một bản tóm tắt các giả định và rủi ro của bạn vào phần kế hoạch tài chính của business case"},{"level":2,"text":"Giả định (assumption)"},{"level":2,"text":"Các yếu tố mà bạn nêu là đúng trong các phép tính để trình bày một kế hoạch tài chính đơn giản hóa"},{"level":2,"text":"Rủi ro (risk) là những sự kiện mà bạn nghĩ có thể xảy ra"},{"level":2,"text":"Việc đưa vào các rủi ro có khả năng xảy ra cao hơn sẽ cân bằng lại sự lạc quan trong các giả định của business case"}]},{"id":"g14","part":2,"title":"Các yếu tố ESG","blocks":[{"level":1,"text":"Các yếu tố Môi trường, Xã hội và Quản trị (Environmental, Social, and Governance - ESG)"},{"level":2,"text":"Đề cập đến các hành động và chương trình của một công ty với mục đích vượt ra ngoài việc đơn thuần kiếm tiền và tối đa hóa lợi nhuận"},{"level":1,"text":"Các yếu tố môi trường (environmental factor)"},{"level":2,"text":"Cách tổ chức tác động đến thế giới tự nhiên"},{"level":2,"text":"Các cân nhắc về môi trường có thể bao gồm"},{"level":2,"text":"Lượng rác chôn lấp (landfill consumption)"},{"level":2,"text":"Việc tạo ra và phương pháp xử lý chất thải (waste generation and disposal method)"},{"level":2,"text":"Ô nhiễm (pollution)"},{"level":2,"text":"Bảo vệ hoặc phá hủy môi trường sống (habitat protection or destruction)"},{"level":2,"text":"Tiêu thụ tài nguyên (resource consumption)"},{"level":1,"text":"Các yếu tố xã hội (social factor)"},{"level":2,"text":"Cách công ty xây dựng các mối quan hệ và đối xử với con người"},{"level":2,"text":"Nhân viên (employee)"},{"level":2,"text":"Người dân trong cộng đồng (people in the community)"},{"level":2,"text":"Các nhóm chịu ảnh hưởng bởi các sản phẩm và dịch vụ của công ty"},{"level":1,"text":"Các yếu tố quản trị (governance factor)"},{"level":2,"text":"Cách công ty vận hành"},{"level":2,"text":"Chính sách (policy)"},{"level":2,"text":"Tính minh bạch (transparency)"},{"level":2,"text":"Cơ cấu (structure)"},{"level":1,"text":"Một công ty phải áp dụng các yếu tố môi trường, xã hội và quản trị khi thực hiện các hoạt động kinh doanh thường xuyên cũng như các dự án tạm thời của mình"},{"level":1,"text":"Thiết lập mối quan hệ với đội pháp chế nội bộ của tổ chức"},{"level":1,"text":"Bản sắc doanh nghiệp (corporate identity)"},{"level":2,"text":"Bao gồm tầm nhìn (vision), tuyên bố sứ mệnh (mission statement), các giá trị (value) và thương hiệu (brand) của công ty"},{"level":2,"text":"Tầm nhìn, sứ mệnh và các giá trị là bản sắc mà công ty chia sẻ qua các tuyên bố công khai, phải phản ánh tinh thần của công ty"},{"level":2,"text":"Thương hiệu của một công ty mô tả cách mọi người thực sự nhìn nhận về công ty"},{"level":2,"text":"Nó có thể bao gồm các yếu tố hữu hình"},{"level":2,"text":"Biểu tượng (symbol)"},{"level":2,"text":"Phối màu (color scheme)"},{"level":2,"text":"Khẩu hiệu hoặc người phát ngôn dễ nhớ (memorable slogan or spokesperson)"},{"level":2,"text":"Nó cũng có thể bao gồm các yếu tố vô hình"},{"level":2,"text":"Cảm nhận chung về cách họ nghĩ về công ty"},{"level":2,"text":"Các đặc điểm hoặc tính cách chung"},{"level":2,"text":"Ảnh hưởng xã hội của công ty"},{"level":2,"text":"Thương hiệu chịu ảnh hưởng bởi người tiêu dùng, nhân viên, thành viên cộng đồng và các đối tác kinh doanh của công ty, chứ không chỉ bởi bộ phận PR"},{"level":1,"text":"Đưa các yếu tố ESG vào thiết kế dự án và việc ra quyết định xuyên suốt vòng đời của dự án (Methodologies and Frameworks)"}]},{"id":"g15","part":3,"title":"Các phương pháp và khuôn khổ","blocks":[{"level":1,"text":"Có rất nhiều loại phương pháp và khuôn khổ khác nhau để quản lý dự án"},{"level":1,"text":"Một khuôn khổ phù hợp có thể đơn giản hóa quy trình quản lý dự án và khuếch đại kết quả của dự án"},{"level":1,"text":"Khuôn khổ (framework)"},{"level":2,"text":"Các quy trình, nhiệm vụ, vai trò và nguyên tắc định hướng tạo nên cấu trúc để hoàn thành công việc"},{"level":2,"text":"Khuôn khổ ảnh hưởng đáng kể đến cách một dự án đi từ khởi đầu đến kết thúc"},{"level":1,"text":"DevOps thúc đẩy tích hợp liên tục, phân phối liên tục và triển khai liên tục (CI/CD)"},{"level":1,"text":"DevSecOps tiến xa hơn một bước bằng cách tích hợp các biện pháp bảo mật xuyên suốt quy trình phát triển"},{"level":1,"text":"Scaled Agile Framework (SAFe)"},{"level":2,"text":"Phương pháp dùng để mở rộng các thực hành Agile ra nhiều đội nhóm trong một tổ chức"},{"level":2,"text":"SAFe phù hợp nhất với các công ty có dự án liên quan đến nhiều đội nhóm cần giao tiếp và hợp tác hiệu quả"},{"level":1,"text":"Software Development Life Cycle (SDLC)"},{"level":2,"text":"Khuôn khổ linh hoạt được thiết kế để tạo ra phần mềm chất lượng cao, chi phí thấp và được kiểm thử kỹ lưỡng thông qua cải tiến liên tục"},{"level":2,"text":"SDLC cũng phụ thuộc nhiều vào việc lập kế hoạch trước kỹ lưỡng, điều này có thể không phù hợp với các đội nhóm định hướng Agile"}]},{"id":"g16","part":3,"title":"Waterfall","blocks":[{"level":1,"text":"Phương pháp Waterfall"},{"level":2,"text":"Một quy trình phát triển tuần tự chảy như thác nước qua mọi giai đoạn của một dự án"},{"level":2,"text":"Ban đầu được dùng trong sản xuất, và sau đó đến với phát triển phần mềm vì nó đã được sử dụng phổ biến vào thời điểm đó, đóng vai trò là điểm khởi đầu sớm"},{"level":2,"text":"Nó tuân theo một trình tự tuyến tính"},{"level":1,"text":"6 giai đoạn của phương pháp Waterfall"},{"level":2,"text":"Yêu cầu (requirements)"},{"level":2,"text":"Xác định các yêu cầu của dự án"},{"level":2,"text":"Thiết kế (design)"},{"level":2,"text":"Chuyển các yêu cầu thành các đặc tả có thể thực hiện được"},{"level":2,"text":"Triển khai (implementation)"},{"level":2,"text":"Hoàn thành công việc như viết mã"},{"level":2,"text":"Kiểm thử (testing)"},{"level":2,"text":"Xác minh rằng công việc đáp ứng các yêu cầu và đặc tả chất lượng"},{"level":2,"text":"Bàn giao (delivery)"},{"level":2,"text":"Còn được gọi là triển khai (deployment), đưa sản phẩm vào môi trường vận hành (production)"},{"level":2,"text":"Bảo trì (maintenance)"},{"level":2,"text":"Giải quyết mọi vấn đề có thể phát sinh"},{"level":1,"text":"Các giai đoạn của Waterfall được hiển thị một cách độc đáo và khác biệt vì chúng xếp tầng từ giai đoạn đầu sang giai đoạn hai rồi giai đoạn ba, v.v., cho đến khi đến giai đoạn cuối cùng"},{"level":1,"text":"Ưu điểm của Waterfall"},{"level":2,"text":"Khuôn khổ Waterfall là khuôn khổ đơn giản nhất mà bạn sẽ được kiểm tra và dễ hiểu, dễ triển khai"},{"level":2,"text":"Tài liệu cần cho các dự án này rất chi tiết"},{"level":1,"text":"Nhược điểm của Waterfall"},{"level":2,"text":"Phương pháp Waterfall không linh hoạt lắm"},{"level":2,"text":"Kế hoạch được thiết kế trước và các thay đổi hoặc chỉnh sửa về sau thường tốn kém về thời gian, tiền bạc hoặc các nguồn lực khác"},{"level":2,"text":"Khiến việc quản lý thay đổi (change management) rất tốn kém trong một dự án dựa trên Waterfall"},{"level":1,"text":"Khi nào chúng ta dùng Waterfall?"},{"level":2,"text":"Yêu cầu cố định, không có điều chưa biết"},{"level":2,"text":"Chi phí thay đổi rất cao"},{"level":2,"text":"Ngắn và đơn giản"},{"level":1,"text":"Quản lý dự án Waterfall là một phương pháp tuyến tính"},{"level":2,"text":"Ưu điểm"},{"level":2,"text":"Đơn giản"},{"level":2,"text":"Dễ hiểu"},{"level":2,"text":"Tài liệu chi tiết"},{"level":2,"text":"Nhược điểm"},{"level":2,"text":"Thiếu linh hoạt"},{"level":2,"text":"Chi phí quản lý thay đổi cao"}]},{"id":"g17","part":3,"title":"Agile","blocks":[{"level":1,"text":"Phương pháp Agile"},{"level":2,"text":"Một cách tiếp cận quản lý dự án trong đó chia dự án thành các giai đoạn và nhấn mạnh sự hợp tác và cải tiến liên tục"},{"level":1,"text":"Sự khác biệt giữa Waterfall và Agile"},{"level":2,"text":"Waterfall"},{"level":2,"text":"Có cấu trúc và mang lại giá trị vào cuối"},{"level":2,"text":"Cách tiếp cận thiết kế lớn ngay từ đầu (big design upfront)"},{"level":2,"text":"Tốt nhất khi không có điều chưa biết"},{"level":2,"text":"Agile"},{"level":2,"text":"Linh hoạt và mang lại giá trị sớm và thường xuyên"},{"level":2,"text":"Lặp đi lặp lại và tăng dần (iterative and incremental)"},{"level":2,"text":"Thích ứng với thay đổi"},{"level":1,"text":"Phát triển lặp (iterative development)"},{"level":2,"text":"Một cách tiếp cận phát triển phần mềm nhấn mạnh việc tinh chỉnh và cải tiến liên tục một hệ thống hoặc sản phẩm"},{"level":2,"text":"Mục tiêu chính của mỗi vòng lặp là xác định các vấn đề, thực hiện cải tiến và đưa vào phản hồi từ người dùng hoặc các bên liên quan"},{"level":2,"text":"Các lợi ích chính"},{"level":2,"text":"Khả năng phản ứng nhanh với các yêu cầu thay đổi hoặc nhu cầu mới của người dùng"},{"level":2,"text":"Cơ hội nhận phản hồi sớm và thường xuyên từ người dùng"},{"level":1,"text":"Phát triển tăng dần (incremental development)"},{"level":2,"text":"Một cách tiếp cận phát triển phần mềm tập trung vào việc bàn giao từng phần nhỏ, có thể hoạt động được của một hệ thống hoặc sản phẩm theo từng bước"},{"level":2,"text":"Các lợi ích chính"},{"level":2,"text":"Giảm rủi ro và kết quả dự án có thể dự đoán được"},{"level":2,"text":"Nhà phát triển quản lý độ phức tạp, giảm thiểu lỗi và duy trì mức kiểm soát cao hơn đối với quy trình phát triển"},{"level":2,"text":"Cho phép bàn giao các tính năng mới nhanh hơn"},{"level":1,"text":"Khi một đội nhóm dùng phát triển lặp và tăng dần, họ sẽ xây dựng từng tính năng một"},{"level":1,"text":"Agile thích ứng tốt với chu kỳ phát hành ngắn hơn, còn Waterfall sẽ cần nhiều thông tin và yêu cầu hơn"},{"level":2,"text":"Tính linh hoạt của nó có thể dẫn đến phình phạm vi (scope creep) và lỡ thời hạn"},{"level":2,"text":"Nó có thể dẫn đến ít tài liệu hơn"},{"level":1,"text":"Hệ thống ERP có thể không phải là ứng cử viên tốt cho Agile"},{"level":1,"text":"Ưu điểm của Agile"},{"level":2,"text":"Khả năng thích ứng"},{"level":2,"text":"Chu kỳ phát hành ngắn hơn"},{"level":2,"text":"Kết quả chất lượng cao hơn"},{"level":1,"text":"Nhược điểm của Agile"},{"level":2,"text":"Nguy cơ phình phạm vi"},{"level":2,"text":"Lỡ thời hạn"},{"level":2,"text":"Ít tài liệu hơn"}]},{"id":"g18","part":3,"title":"Scrum","blocks":[{"level":1,"text":"Scrum là khuôn khổ Agile phổ biến nhất; nó mang lại giá trị lặp đi lặp lại và thích ứng đồng thời chỉ cố tình bao phủ những yêu cầu tối thiểu nhất"},{"level":2,"text":"Nó dùng chủ nghĩa kinh nghiệm (empiricism) và tư duy tinh gọn (lean thinking) để liên tục cải thiện kết quả"},{"level":2,"text":"Chủ nghĩa kinh nghiệm khuyến khích các đội nhóm đưa ra quyết định dựa trên những gì họ thấy và biết"},{"level":2,"text":"Đó là việc dựa vào quan sát và thử nghiệm"},{"level":2,"text":"Nói cách khác, hãy nhìn vào những gì đã xảy ra thay vì cố dự đoán những gì có thể xảy ra"},{"level":2,"text":"Tư duy tinh gọn (lean thinking)"},{"level":2,"text":"Nó tập trung vào việc thúc đẩy hiệu quả cao hơn bằng cách giảm lãng phí, dư thừa và các công việc không cần thiết khác trong một dự án"},{"level":1,"text":"5 giá trị cốt lõi của Scrum"},{"level":2,"text":"Cam kết (commitment)"},{"level":2,"text":"Tập trung (focus)"},{"level":2,"text":"Cởi mở (openness)"},{"level":2,"text":"Tôn trọng (respect)"},{"level":2,"text":"Dũng cảm (courage)"},{"level":1,"text":"3 trụ cột nền tảng của Scrum"},{"level":2,"text":"Minh bạch (transparency)"},{"level":2,"text":"Đảm bảo rằng mọi thành viên đội nhóm đều hiểu rõ tiến độ, mục tiêu của dự án và bất kỳ thách thức nào đang đối mặt"},{"level":2,"text":"Thanh tra (inspection)"},{"level":2,"text":"Bao gồm việc thường xuyên xem xét và đánh giá công việc đang thực hiện, cũng như các quy trình mà đội nhóm dùng"},{"level":2,"text":"Thích ứng (adaptation)"},{"level":2,"text":"Quy trình thực hiện các điều chỉnh cần thiết để đáp lại các phát hiện từ việc thanh tra"},{"level":1,"text":"4 bước cơ bản của quy trình Scrum"},{"level":2,"text":"Product owner ưu tiên công việc vào product backlog"},{"level":2,"text":"Đội Scrum chọn các mục hàng đầu trong backlog đó"},{"level":2,"text":"Đội Scrum và các bên liên quan xem xét kết quả của sprint"},{"level":2,"text":"Các bước lặp lại chừng nào product backlog còn tồn tại"},{"level":1,"text":"4 vai trò trong Scrum"},{"level":2,"text":"Đội Scrum (scrum team)"},{"level":2,"text":"Nhóm người cùng làm việc để bàn giao các bước tăng giá trị (increment of value)"},{"level":2,"text":"Product owner"},{"level":2,"text":"Tạo, duy trì và sở hữu product backlog"},{"level":2,"text":"Scrum master"},{"level":2,"text":"Huấn luyện viên của đội nhóm, giúp đội nhóm, product owner và tổ chức cải thiện việc thực hành Scrum"},{"level":2,"text":"Developer"},{"level":2,"text":"Mô tả các thành viên đội nhóm còn lại và không chỉ giới hạn ở kỹ sư phần mềm"},{"level":1,"text":"Scrum master và quản lý dự án không phải là cùng một vai trò"},{"level":1,"text":"Các hiện vật và thuật ngữ chính của Scrum"},{"level":2,"text":"Product backlog"},{"level":2,"text":"Danh sách có thứ tự các thay đổi hoặc cải tiến của sản phẩm"},{"level":2,"text":"Product goal"},{"level":2,"text":"Mô tả mục tiêu dài hạn của sản phẩm, và product backlog phải phục vụ product goal"},{"level":2,"text":"Sprint backlog"},{"level":2,"text":"Bao gồm những gì đội nhóm sẽ làm, vì sao họ cho rằng nó quan trọng, và họ sẽ làm nó như thế nào"},{"level":2,"text":"Sprint goal"},{"level":2,"text":"Tóm tắt giá trị của sprint"},{"level":2,"text":"Increment"},{"level":2,"text":"Một khối công việc hoàn chỉnh đáp ứng định nghĩa hoàn thành (definition of done) và tiến về product goal"},{"level":1,"text":"Một sprint có thể có một hoặc nhiều increment"},{"level":2,"text":"Mỗi increment cần một definition of done để tạo sự hiểu chung về những gì cần thiết để tiến lên"},{"level":1,"text":"Các sự kiện Scrum khác nhau"},{"level":2,"text":"Sprint"},{"level":2,"text":"Vòng lặp của Scrum và là vật chứa cho mọi sự kiện Scrum khác"},{"level":2,"text":"Sprint planning"},{"level":2,"text":"Kéo dài tối đa tám giờ đối với các sprint một tháng, và còn ít hơn đối với các sprint ngắn hơn"},{"level":2,"text":"Daily scrum"},{"level":2,"text":"Nơi các developer gặp nhau để xem xét tiến độ hướng tới sprint goal rồi lập kế hoạch cho 24 giờ làm việc tiếp theo"},{"level":2,"text":"Sprint review"},{"level":2,"text":"Phát hiện sớm các vấn đề khi chúng còn nhỏ và dễ sửa, hé lộ các ý tưởng phát triển chưa từng biết trước đây, hoặc xác nhận rằng đội nhóm đang đi đúng hướng"},{"level":2,"text":"Sprint retrospective"},{"level":2,"text":"Diễn ra khi đội nhóm kiểm điểm cách họ đã làm việc trong sprint vừa qua và xác định các cơ hội cải tiến"},{"level":2,"text":"Buổi retrospective tập trung vào đội Scrum và cách họ có thể cải thiện việc phối hợp cùng nhau"},{"level":1,"text":"Ưu điểm của Scrum"},{"level":2,"text":"Scrum linh hoạt và có thể dùng trong mọi ngành, và các chu kỳ ngắn của nó cho phép học tập đáp ứng nhanh và giải quyết các vấn đề phức tạp"},{"level":1,"text":"Nhược điểm của Scrum"},{"level":2,"text":"Scrum phụ thuộc vào việc tổ chức tôn trọng các quyết định của product owner về backlog và các ưu tiên"},{"level":2,"text":"Khuôn khổ của Scrum được thiết kế cho một đội nhóm đơn lẻ, hiệu suất cao và đa chức năng, điều này có nghĩa là các đội nhóm ít kinh nghiệm có thể gặp khó khăn và việc mở rộng lên các nhóm lớn hơn có thể khó khăn"},{"level":1,"text":"Scrum phù hợp nhất với các đội nhóm gắn kết cao, đa chức năng, tập trung vào cải tiến liên tục"},{"level":1,"text":"Phương pháp Scrum là một khuôn khổ Agile nhẹ nhàng, lấy khách hàng làm trung tâm, tập trung vào giá trị lặp đi lặp lại và thích ứng"}]},{"id":"g19","part":3,"title":"Kanban","blocks":[{"level":1,"text":"Kanban được dùng để kiểm soát mức độ công việc đang thực hiện (work in progress - WIP) và quản lý quy trình làm việc trong các quy trình phần mềm và kinh doanh"},{"level":1,"text":"6 thực hành cốt lõi của Kanban"},{"level":2,"text":"Trực quan hóa công việc (visualizing work)"},{"level":2,"text":"Tạo một bảng Kanban (Kanban board) cho thấy các giai đoạn cụ thể mà công việc di chuyển qua trong đội nhóm của bạn"},{"level":2,"text":"Giới hạn công việc đang thực hiện (limit work in progress)"},{"level":2,"text":"Ngăn các thành viên đội nhóm bị quá tải và giúp tăng năng suất cũng như giảm suy giảm chất lượng sản phẩm"},{"level":2,"text":"Làm cho các chính sách trở nên rõ ràng (make policies explicit)"},{"level":2,"text":"Xác định rõ ràng cách công việc được hoàn thành và di chuyển từ giai đoạn này sang giai đoạn khác"},{"level":2,"text":"Quản lý dòng chảy (manage flow)"},{"level":2,"text":"Điều này kế thừa gốc rễ của sản xuất tinh gọn và giảm lãng phí trong hệ thống"},{"level":2,"text":"Triển khai các vòng lặp phản hồi (implement feedback loop)"},{"level":2,"text":"Bạn đưa phản hồi trực tiếp vào hệ thống và luôn nắm được thông tin về hiệu quả hoạt động"},{"level":2,"text":"Cải tiến hợp tác đồng thời tiến hóa theo thực nghiệm (improve collaboratively, evolve experimentally)"},{"level":2,"text":"Điều này có nghĩa là chúng ta cần dùng phương pháp khoa học để kiểm thử các ý tưởng và đo lường kết quả trong các tín hiệu Kanban (Kanban signal)"},{"level":1,"text":"Mục tiêu của Kanban là bắt đầu ngay và không ngừng cải tiến"},{"level":2,"text":"Đặc điểm dễ nhận biết nhất của nó là bảng Kanban"},{"level":2,"text":"Công việc di chuyển qua ba giai đoạn cơ bản: To Do, In Progress và Done"},{"level":1,"text":"Quy trình bốn phần của Kanban"},{"level":2,"text":"Product owner ưu tiên và sắp xếp backlog"},{"level":2,"text":"Một thành viên đội nhóm chọn mục được xếp hạng cao nhất trong backlog và kéo nó vào giai đoạn đang thực hiện"},{"level":2,"text":"Đội nhóm di chuyển mục công việc qua quy trình, giữ trong giới hạn công việc đang thực hiện"},{"level":2,"text":"Khi đội nhóm sẵn sàng bắt đầu công việc mới, họ chọn mục tiếp theo trong backlog"},{"level":1,"text":"Sự khác biệt giữa Scrum và Kanban"},{"level":2,"text":"Scrum"},{"level":2,"text":"Giúp các đội nhóm giải quyết các vấn đề phức tạp"},{"level":2,"text":"Tốt hơn cho công việc khó dự đoán"},{"level":2,"text":"Kanban"},{"level":2,"text":"Giúp các đội nhóm tập trung vào một lượng công việc hợp lý"},{"level":2,"text":"Vượt trội ở hầu hết các nhiệm vụ thường lệ"},{"level":1,"text":"Các đội Scrum thường dùng bảng Kanban để trực quan hóa công việc của họ"},{"level":1,"text":"Các đội Kanban dùng các buổi demo và retrospective để thu thập phản hồi và cải thiện quy trình của họ"},{"level":1,"text":"Các đội Agile thậm chí được phân loại thành Scrum, Kanban hoặc Scrumban"},{"level":1,"text":"Ưu điểm của Kanban"},{"level":2,"text":"Kanban là khuôn khổ Agile đơn giản nhất để học và có thể áp dụng cho mọi ngành"},{"level":2,"text":"Nó nhẹ nhàng và tập trung vào công việc thường lệ hơn là lập kế hoạch vòng lặp"},{"level":1,"text":"Nhược điểm của Kanban"},{"level":2,"text":"Kanban có thể kém hiệu quả hơn nếu đội nhóm quá đông hoặc có tỷ lệ thay đổi nhân sự cao"},{"level":2,"text":"Các sai sót hoặc thay đổi giữa các mục công việc có thể làm gián đoạn sự tập trung của đội nhóm, và thời gian chu kỳ (cycle time) có thể bị kéo dài khi không có các vòng lặp cố định, nếu hiệu quả hoạt động không được quản lý đúng cách"},{"level":1,"text":"Kanban hiệu quả nhất cho các đội nhóm có backlog thay đổi thường xuyên"},{"level":1,"text":"Kanban là một phương pháp Agile có nguồn gốc từ sản xuất tinh gọn và hiện được áp dụng cho phát triển phần mềm và các quy trình kinh doanh khác"},{"level":1,"text":"Kanban và Scrum giải quyết các vấn đề khác nhau và có thể được kết hợp trong một số dự án thành cái gọi là \"Scrumban\""}]},{"blocks":[{"level":1,"text":"Extreme Programming (hay XP) là một loại framework Agile khác được thiết kế đặc biệt cho việc phát triển phần mềm"},{"level":2,"text":"Nó hướng đến việc tạo ra chất lượng cuộc sống tốt hơn cho lập trình viên và phần mềm tốt hơn cho khách hàng"},{"level":2,"text":"Nó tin tưởng vào tuần làm việc 40 giờ cùng với việc phát hành thường xuyên và lấy khách hàng làm trung tâm (customer centricity)"},{"level":1,"text":"5 giá trị trong framework Extreme Programming"},{"level":2,"text":"Giao tiếp (Communication)"},{"level":2,"text":"Đơn giản (Simplicity)"},{"level":2,"text":"Phản hồi (Feedback)"},{"level":2,"text":"Tôn trọng (Respect)"},{"level":2,"text":"Can đảm (Courage)"},{"level":1,"text":"Phương pháp Extreme Programming còn nổi tiếng với các nguyên tắc và thực hành độc đáo của mình, chẳng hạn như việc nhấn mạnh tính đơn giản — ưu tiên giải pháp cần ít code nhất hoặc ít công sức nhất"},{"level":1,"text":"3 vai trò trong Extreme Programming"},{"level":2,"text":"Khách hàng (Customer)"},{"level":2,"text":"Quyết định tính năng nào cần thiết và tính năng nào cần làm tiếp theo"},{"level":2,"text":"Người theo dõi (Tracker)"},{"level":2,"text":"Thu thập chỉ số (metrics), đo lường tiến độ và tìm kiếm cơ hội cải tiến"},{"level":2,"text":"Huấn luyện viên (Coach)"},{"level":2,"text":"Hướng dẫn các thành viên trong nhóm cách sử dụng các thực hành của Extreme Programming"},{"level":1,"text":"Các thực hành phổ biến nhất trong Extreme Programming"},{"level":2,"text":"Lập trình cặp (Paired Programming)"},{"level":2,"text":"Hai kỹ sư phần mềm ngồi cạnh nhau cùng viết code một lúc"},{"level":2,"text":"Build trong 10 phút (Ten-minute Building)"},{"level":2,"text":"Quy định rằng việc build, kiểm thử và triển khai toàn bộ hệ thống phải mất chưa đầy 10 phút"},{"level":2,"text":"Tích hợp liên tục (Continuous Integration)"},{"level":2,"text":"Hợp nhất code cục bộ vào kho code chính (main repository) ít nhất vài lần mỗi ngày"},{"level":2,"text":"Lập trình kiểm thử trước (Test-First Programming)"},{"level":2,"text":"Một thực hành trong đó lập trình viên viết các bài kiểm thử trước, rồi mới viết code để vượt qua các bài kiểm thử đó"},{"level":1,"text":"Extreme Programming áp dụng thiết kế tăng dần (incremental design)"},{"level":1,"text":"User story cũng được dùng để truyền đạt yêu cầu (requirements)"},{"level":2,"text":"Nhu cầu của người dùng được viết dưới dạng ngắn gọn, có tính mô tả, thể hiện rõ người dùng muốn gì và điều đó sẽ giúp ích cho họ như thế nào"},{"level":1,"text":"Extreme Programming sử dụng khái niệm khoảng đệm (slack) trong lịch làm việc của các nhóm"},{"level":1,"text":"Ưu điểm của Extreme Programming"},{"level":2,"text":"Rất hiệu quả"},{"level":2,"text":"Tích hợp liên tục, tự động hóa và tốc độ thích ứng cao"},{"level":2,"text":"Các thực hành tập trung vào nhóm và ít dự án thất bại hơn"},{"level":1,"text":"Nhược điểm của Extreme Programming"},{"level":2,"text":"Phạm vi áp dụng hạn chế"},{"level":2,"text":"Các thực hành thiên về code có thể dẫn đến thiết kế kém tối ưu"},{"level":2,"text":"Nhịp độ công việc nhanh có thể gây căng thẳng"},{"level":2,"text":"Tài liệu tối thiểu có thể cản trở thành viên mới hiểu công việc"},{"level":2,"text":"Phụ thuộc vào tương tác trực tiếp giữa các thành viên trong nhóm và khách hàng"},{"level":1,"text":"Extreme Programming phù hợp nhất với các nhóm nhỏ, ngồi cùng một chỗ, có thể xử lý các yêu cầu chưa rõ ràng với thời hạn gấp và có khả năng tự động hóa kiểm thử"}],"id":"g20","part":3,"title":"Extreme Programming"},{"blocks":[{"level":1,"text":"DevOps"},{"level":2,"text":"Một tập hợp các thực hành và công cụ tích hợp và tự động hóa công việc phát triển phần mềm và vận hành IT như một phương tiện để cải thiện và rút ngắn vòng đời phát triển hệ thống (systems development life cycle)"},{"level":1,"text":"2 nhóm trong quy trình phân phối phần mềm (Software Delivery Process)"},{"level":2,"text":"Phát triển phần mềm (Software Development)"},{"level":2,"text":"Nhóm phát triển thiết kế và tạo ra phần mềm qua bốn giai đoạn của quy trình làm việc: plan (lập kế hoạch), code (viết code), build và test (kiểm thử)"},{"level":2,"text":"Vận hành IT (IT Operations)"},{"level":2,"text":"Sau đó, nhóm vận hành sẽ triển khai và hỗ trợ phần mềm qua bốn giai đoạn của quy trình làm việc: release (ra mắt), deploy (triển khai), operate (vận hành) và monitor (giám sát)"},{"level":1,"text":"DevOps xóa bỏ rào cản giữa phát triển và vận hành"},{"level":2,"text":"Nó bao gồm các thực hành, công cụ và văn hóa của việc tích hợp phát triển với vận hành, và phân phối công việc với tần suất phù hợp khi cần"},{"level":1,"text":"DevOps tăng tốc độ xử lý (throughput) nhờ tự động hóa và giảm lỗi nhờ phát hiện sớm"},{"level":1,"text":"Tích hợp liên tục (Continuous Integration, CI)"},{"level":2,"text":"Từng lập trình viên đưa code của mình vào nhánh chính (main branch) thường xuyên, và các bài kiểm thử tự động chạy trên code mới"},{"level":1,"text":"Phân phối liên tục (Continuous Delivery, CD)"},{"level":2,"text":"Chuẩn bị code để phát hành lên môi trường production"},{"level":1,"text":"Triển khai liên tục (Continuous Deployment, CD)"},{"level":2,"text":"Sau khi tích hợp, quy trình triển khai liên tục chuẩn bị code để phát hành lên production và triển khai nó lên production"},{"level":1,"text":"Điểm mạnh của DevOps"},{"level":2,"text":"Tuyệt vời cho các nhóm muốn phát hành code thường xuyên"},{"level":2,"text":"Các công ty muốn giảm ma sát (friction)"},{"level":2,"text":"Các tổ chức có nguồn lực để bố trí các nhóm đa chức năng (cross-functional teams)"},{"level":1,"text":"Điểm yếu của DevOps"},{"level":2,"text":"Đòi hỏi chuyên môn đáng kể, và các nhóm có thể gặp khó khăn trong việc tìm đủ thành viên có kỹ năng cần thiết"},{"level":2,"text":"Các hệ thống lớn hoặc hệ thống cũ (legacy) với mức tự động hóa tối thiểu sẽ khó chuyển đổi nhanh sang DevOps"},{"level":1,"text":"DevOps không phải là một phương pháp quản lý dự án, nhưng nó điều phối quy trình kỹ thuật phần mềm (software engineering process)"},{"level":1,"text":"DevSecOps"},{"level":2,"text":"Một thực hành phát triển trong đó các quy trình bảo mật, như kiểm toán bảo mật (security audits) và kiểm thử, được tự động hóa và tích hợp xuyên suốt quá trình phát triển"},{"level":2,"text":"DevSecOps tạo ra trách nhiệm chung, nơi mọi người trong nhóm đều quan tâm và chịu trách nhiệm về bảo mật của sản phẩm"},{"level":2,"text":"Mô hình bảo mật phi tập trung này đòi hỏi một sự thay đổi lớn về văn hóa"},{"level":2,"text":"Tất cả chúng ta cần hiểu rủi ro bảo mật và áp dụng tốt an ninh vận hành (operational security)"},{"level":1,"text":"DevOps và DevSecOps là hai cách tiếp cận tích hợp phát triển phần mềm và vận hành IT để cải thiện vòng đời phát triển hệ thống"},{"level":2,"text":"DevOps thúc đẩy tích hợp liên tục, phân phối liên tục và triển khai liên tục (CI/CD), giúp phân phối code chất lượng cao nhanh hơn"},{"level":2,"text":"DevSecOps tiến thêm một bước bằng cách lồng ghép các biện pháp bảo mật xuyên suốt quá trình phát triển, tạo ra trách nhiệm chung về bảo mật trong toàn nhóm"}],"id":"g21","part":3,"title":"DevOps & DevSecOps"},{"blocks":[{"level":1,"text":"Scaled Agile Framework (SAFe)"},{"level":2,"text":"Một phương pháp dùng để mở rộng các thực hành Agile ra nhiều nhóm trong một tổ chức"},{"level":2,"text":"Tạo sự cân bằng giữa việc giữ các nhóm đồng nhất với nhau và bảo toàn tính tự chủ của từng nhóm"},{"level":1,"text":"Scaled Agile"},{"level":2,"text":"Thuật ngữ dùng để mô tả bất kỳ phương pháp nào mở rộng các công cụ Agile ra hơn một nhóm"},{"level":1,"text":"SAFe nổi bật như một framework toàn diện về năng lực Agile của doanh nghiệp (business agility) và được sử dụng miễn phí"},{"level":1,"text":"SAFe trực quan hóa các vai trò, thực hành, sự kiện và sản phẩm công việc (artifacts) nổi bật trên bức tranh tổng thể có tính tương tác của nó"},{"level":1,"text":"Một số thuật ngữ chính về SAFe"},{"level":2,"text":"Nhóm Agile (Agile Team)"},{"level":2,"text":"Các nhóm gồm từ ba đến mười người đa chức năng (cross-functional) cùng làm việc để phân phối các phần giá trị tăng dần (increments of value)"},{"level":2,"text":"Tuyến phát hành Agile (Agile Release Train, ART)"},{"level":2,"text":"Gom các nhóm liên quan lại để đơn giản hóa giao tiếp, lập kế hoạch và lịch trình"},{"level":2,"text":"Vòng lặp (Iteration)"},{"level":2,"text":"Phương pháp Agile phát triển sản phẩm theo từng vòng lặp với các khoảng thời gian cố định"},{"level":2,"text":"Phần tăng trưởng của chương trình (Program Increment)"},{"level":2,"text":"Tương tự như chu kỳ quý trong Extreme Programming, và nó đóng vai trò là chu kỳ lập kế hoạch dài hạn hơn"},{"level":2,"text":"Một program increment là một khoảng tăng trưởng có độ dài cố định, kéo dài 8-12 tuần thay vì ba tháng"},{"level":2,"text":"Nó là một khung thời gian chung (timebox) cho tất cả các nhóm trên một ART"},{"level":2,"text":"Lập kế hoạch Program Increment (Program Increment Planning)"},{"level":2,"text":"Đóng vai trò là sự kiện lập kế hoạch của ART và tương tự như lập kế hoạch sprint (sprint planning) cho một nhóm Scrum đơn lẻ"},{"level":1,"text":"Điểm mạnh của SAFe"},{"level":2,"text":"SAFe rất tốt trong việc mang lợi ích của Agile đến các tổ chức lớn hơn và đáp ứng nhu cầu mở rộng (scaling)"},{"level":1,"text":"Điểm yếu của SAFe"},{"level":2,"text":"Cần thêm các lớp thuật ngữ, chi phí phụ (overhead), tổ chức và nhân sự, điều này có thể làm chậm cách tiếp cận từ dưới lên (ground-up) của Agile"}],"id":"g22","part":3,"title":"Scaled Agile Framework (SAFe)"});
